package com.franco.desco.application.crates.service;import com.franco.desco.application.crates.*;import com.franco.desco.application.crates.port.in.CrateUseCase;import com.franco.desco.application.crates.port.out.CratePersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.crates.CrateModels;import java.util.List;
public final class CrateApplicationService implements CrateUseCase{private final CratePersistencePort p;public CrateApplicationService(CratePersistencePort p){this.p=p;}public AppResult<PageResult<CrateModels.Summary>>list(CrateCommands.ListCrates c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"JABAS_LISTADAS","JABAS_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<CrateModels.Balance>balance(CrateCommands.Balance c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.balance(c,i,m),"SALDO_JABAS_CONSULTADO","SALDO_JABAS_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<List<CrateModels.History>>history(CrateCommands.History c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.history(c,i,m),"HISTORIAL_JABAS_CARGADO","HISTORIAL_JABAS_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>receive(CrateCommands.Receive c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.receive(c,i,m),"JABAS_RECIBIDAS","JABAS_NO_RECIBIDAS");}public AppResult<Long>assign(CrateCommands.Assign c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.assign(c,i,m),"JABAS_ASIGNADAS","JABAS_NO_ASIGNADAS");}public AppResult<Long>returnCrates(CrateCommands.ReturnCrates c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.returnCrates(c,i,m),"JABAS_DEVUELTAS","JABAS_NO_DEVUELTAS");}public AppResult<Void>annul(CrateCommands.Annul c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.annul(c,i,m),"MOVIMIENTO_JABAS_ANULADO","MOVIMIENTO_JABAS_NO_ANULADO",AppStatus.BAD_REQUEST);}}
